<?php declare(strict_types=1); require_once __DIR__.'/../shared/response.php'; require_once __DIR__.'/../shared/request.php'; require_once __DIR__.'/../shared/auth.php'; methodOnly('PUT'); requireAdmin(); safeApi(function():void{$db=apiDatabase();$id=requestId();$i=jsonRequest();$allowed=['category_id','name','slug','description','sort_order','status'];$set=[];$p=[':id'=>$id];foreach($allowed as $f)if(array_key_exists($f,$i)){$set[]="$f=:$f";$p[":$f"]=$i[$f];}if(!$set)jsonResponse(false,'No fields to update.',null,[],422);$s=$db->prepare('UPDATE sub_categories SET '.implode(',',$set).' WHERE id=:id');$s->execute($p);if(!$s->rowCount())jsonResponse(false,'Sub category not found or unchanged.',null,[],404);jsonResponse(true,'Sub category updated.');});
